public class PipelineService {
    private final PipelineStore s;
    private final ConnectorAdapter connector;
    public Map<String,Object> paginate(Map<String,Object>page,int limit,String cursor){return s.paginate(page,limit,cursor);}
    public PipelineService(PipelineStore s,ConnectorAdapter connector){this.s=s;this.connector=connector;}
    private Map<String,Object> source(UUID id,boolean lock){return s.one(SELECT_DATA_SOURCES_7+(lock?" FOR UPDATE":""),id);}
    private Map<String,Object> policyResponse(Map<String,Object>r){return map("source_id",r.get("source_id"),"source_version",r.get("version"),"license_version",r.get("license_version"),"allow_storage",r.get("allow_storage"),"allow_training",r.get("allow_training"),"status","ACTIVE".equals(r.get("status"))?"PERMITTED":"REVOKED");}
    private void validateSourceUri(String value){try{var uri=java.net.URI.create(value);require(Set.of("http","https").contains(uri.getScheme())&&uri.getHost()!=null&&uri.getUserInfo()==null&&uri.getFragment()==null,400,"SOURCE_URI_INVALID");}catch(IllegalArgumentException error){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"SOURCE_URI_INVALID");}}
    private Map<String,Object> sourceResponse(Map<String,Object>r){var b=policyResponse(r);b.putAll(map("name",r.get("name"),"uri",r.get("uri"),"secret_reference",r.get("credential_secret_ref"),"version",r.get("version")));return b;}
    public Map<String,Object> sources(UUID source){if(source!=null)return sourceResponse(source(source,false));var rows=s.queryForList(SELECT_DATA_SOURCES_8);return s.page(rows.stream().map(this::sourceResponse).toList(),rows.stream().mapToLong(r->number(r.get("version"))).sum()+rows.size());}
    public Map<String,Object> policy(UUID source){return policyResponse(source(source,false));}
    public Map<String,Object> policies(List<UUID>ids){require(!ids.isEmpty()&&ids.size()<=100&&new HashSet<>(ids).size()==ids.size(),400,"INVALID_IDS");var items=new ArrayList<Object>();var missing=new ArrayList<UUID>();for(var id:ids){var rows=s.queryForList(SELECT_DATA_SOURCES_7,id);if(rows.isEmpty())missing.add(id);else items.add(policyResponse(rows.getFirst()));}return map("items",items,"missing_ids",missing);}
    public Map<String,Object> links(UUID source,List<String>ids){require(ids.size()<=100,400,"INVALID_IDS");var items=new ArrayList<Object>();var missing=new ArrayList<String>();for(var id:ids){var rows=s.queryForList(SELECT_SOURCE_PLACE_LINKS_9,source,id);if(rows.isEmpty())missing.add(id);else{var r=rows.getFirst();items.add(map("source_id",source,"external_id",id,"place_id",r.get("place_id")));}}return map("items",items,"missing_ids",missing);}
    private void permitted(Map<String,Object>source){require("ACTIVE".equals(source.get("status"))&&Boolean.TRUE.equals(source.get("allow_storage")),422,"SOURCE_STORAGE_NOT_PERMITTED");}
    public void guardActor(UUID actor){s.guardActor(actor);}
    private void audit(UUID actor,String entity,UUID id,String action){s.guardActor(actor);s.update(INSERT_AUDIT_LOGS_10,UUID.randomUUID(),actor,entity,id.toString(),action);}
    public Map<String,Object> createSource(UUID actor,Map<String,Object>b){s.guardActor(actor);UUID id=UUID.randomUUID();String ref=text(b,"secret_reference",1024);require(ref.equals("none")||ref.matches("env:[A-Z][A-Z0-9_]*"),400,"SECRET_REFERENCE_REQUIRED");require(b.get("allow_storage") instanceof Boolean&&b.get("allow_training") instanceof Boolean,400,"INVALID_POLICY");validateSourceUri(text(b,"uri",262144));s.update(INSERT_DATA_SOURCES_11,id,id.toString(),text(b,"name",1024),text(b,"license_version",1024),b.get("allow_storage"),b.get("allow_training"),ref,b.get("uri"));audit(actor,"source",id,"CREATED");publishPolicy(source(id,false));return sources(id);}
    private void publishPolicy(Map<String,Object>r){s.event((UUID)r.get("source_id"),number(r.get("version")),"ingestion.source-policy.changed.v1",policyResponse(r));}
    public Map<String,Object> patchSource(UUID actor,UUID id,String expected,Map<String,Object>b,boolean onlyPolicy){s.guardActor(actor);var r=source(id,true);require(number(r.get("version"))==version(expected),409,"VERSION_CONFLICT");var full=sourceResponse(r);full.putAll(b);String ref=full.get("secret_reference").toString();require(ref.equals("none")||ref.matches("env:[A-Z][A-Z0-9_]*"),400,"SECRET_REFERENCE_REQUIRED");require(full.get("allow_storage") instanceof Boolean&&full.get("allow_training") instanceof Boolean,400,"INVALID_POLICY");validateSourceUri(text(full,"uri",262144));String status=full.get("status").toString();require(Set.of("PERMITTED","REVOKED").contains(status),400,"INVALID_SOURCE_STATUS");s.update(UPDATE_DATA_SOURCES_12,text(full,"name",1024),text(full,"uri",262144),text(full,"license_version",1024),full.get("allow_storage"),full.get("allow_training"),ref,status.equals("PERMITTED")?"ACTIVE":"REVOKED",id);audit(actor,"source",id,"POLICY_CHANGED");publishPolicy(source(id,false));if(!Boolean.TRUE.equals(full.get("allow_storage"))||status.equals("REVOKED")){s.update(UPDATE_IMPORT_JOBS_13,id);s.update(UPDATE_OUTBOX_EVENTS_14,id.toString());}return onlyPolicy?policy(id):sources(id);}
    public void revokeSource(UUID actor,UUID id,String expected){patchSource(actor,id,expected,map("status","REVOKED","allow_storage",false,"allow_training",false),true);}
    private Map<String,Object> jobResponse(Map<String,Object>r){return map("job_id",r.get("job_id"),"source_id",r.get("source_id"),"status",r.get("status"),"mode",r.get("mode"),"checkpoint",r.get("cursor_after")==null?null:Objects.toString(s.decode(r.get("cursor_after")).getOrDefault("checkpoint",s.decode(r.get("cursor_after")).get("cursor")),null),"version",r.get("version"));}
    public Map<String,Object> job(UUID id){return jobResponse(s.one(SELECT_IMPORT_JOBS_15,id));}
    public Map<String,Object> createJob(UUID actor,UUID source,String key,String mode){s.guardActor(actor);var src=source(source,true);permitted(src);require(key!=null&&!key.isBlank()&&key.length()<=120,428,"IDEMPOTENCY_KEY_REQUIRED");require(Set.of("FULL","INCREMENTAL","REPLAY").contains(mode),400,"INVALID_MODE");var prior=s.queryForList(SELECT_IMPORT_JOBS_16,source,key);if(!prior.isEmpty()){require(mode.equals(prior.getFirst().get("mode")),409,"IDEMPOTENCY_CONFLICT");return jobResponse(prior.getFirst());}require(s.queryForObject(SELECT_IMPORT_JOBS_17,Long.class,source)==0,409,"SOURCE_JOB_ACTIVE");UUID job=UUID.randomUUID();var checkpoints=s.queryForList(SELECT_SOURCE_CHECKPOINTS_18,source);String cursor=mode.equals("INCREMENTAL")&&!checkpoints.isEmpty()?checkpoints.getFirst().get("cursor_value").toString():null;s.update(INSERT_IMPORT_JOBS_19,job,source,key,mode,actor,cursor,src.get("version"));audit(actor,"job",job,"QUEUED");return job(job);}
    public List<UUID> pendingJobs(){return s.queryForList(SELECT_IMPORT_JOBS_20,UUID.class);}
    public void process(UUID jobId){var job=s.one(SELECT_IMPORT_JOBS_21,jobId);if(!Set.of("QUEUED","RUNNING").contains(job.get("status"))||Boolean.TRUE.equals(job.get("fetch_complete")))return;UUID source=(UUID)job.get("source_id");var src=source(source,true);permitted(src);require(number(src.get("version"))==number(job.get("source_version")),409,"SOURCE_POLICY_CHANGED");s.update(UPDATE_IMPORT_JOBS_22,jobId);
        if("REPLAY".equals(job.get("mode"))){var raws=s.queryForList(SELECT_RAW_RECORDS_23,source);for(var raw:raws)ingest(jobId,src,s.decode(raw.get("payload")));s.update(UPDATE_IMPORT_JOBS_24,jobId);settle(jobId);return;}
        String cursor=null;if(job.get("cursor_after")!=null)cursor=Objects.toString(s.decode(job.get("cursor_after")).get("cursor"),null);else if(job.get("cursor_before")!=null)cursor=Objects.toString(s.decode(job.get("cursor_before")).get("cursor"),null);
        var page=connector.fetch(src.get("uri").toString(),cursor,Objects.toString(src.get("credential_secret_ref"),null));for(Object record:(List<?>)page.get("records")){if(record instanceof Map<?,?>){@SuppressWarnings("unchecked")var raw=(Map<String,Object>)record;ingest(jobId,src,raw);}else ingest(jobId,src,map("invalid_record_type",record==null?"NULL":record instanceof List<?>?"ARRAY":record instanceof String?"STRING":record instanceof Number?"NUMBER":"BOOLEAN","invalid_record",record));}Object next=page.get("next_cursor");require(next==null||!next.equals(cursor),422,"CURSOR_DID_NOT_ADVANCE");s.update(UPDATE_IMPORT_JOBS_25,s.encode(map("cursor",next,"checkpoint",page.getOrDefault("checkpoint",next==null?cursor:next))),next==null,jobId);settle(jobId);
    }
    public static String hash(Object value){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private Object canonical(Object value){if(value instanceof Map<?,?> m){var sorted=new TreeMap<String,Object>();m.forEach((k,v)->sorted.put(k.toString(),canonical(v)));return sorted;}if(value instanceof List<?>l)return l.stream().map(this::canonical).toList();return value;}
    private Map<String,Object> normalize(Map<String,Object>raw){String name=Normalizer.normalize(text(raw,"name",1024),Normalizer.Form.NFC).replaceAll("\\s+"," ");double lat=Double.parseDouble(raw.get("latitude").toString()),lon=Double.parseDouble(raw.get("longitude").toString());require(Double.isFinite(lat)&&Double.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180,422,"INVALID_COORDINATES");require("VND".equals(raw.get("currency")),422,"INVALID_CURRENCY");require(raw.get("category_ids") instanceof List<?> categories&&!categories.isEmpty()&&categories.size()<=100,422,"INVALID_CATEGORIES");((List<?>)raw.get("category_ids")).forEach(vn.smarttravel.ingestion.shared.web.ApiValues::id);Object price=null;if(raw.get("price")!=null){var amount=new java.math.BigDecimal(raw.get("price").toString());require(amount.signum()>=0&&Double.isFinite(amount.doubleValue()),422,"INVALID_PRICE");price=amount;}Object hours=raw.getOrDefault("opening_hours",List.of());require(hours instanceof List<?> && ((List<?>)hours).size()<=28,422,"INVALID_OPENING_HOURS");for(Object h:(List<?>)hours){require(h instanceof Map<?,?>,422,"INVALID_OPENING_HOURS");var slot=(Map<?,?>)h;require(number(slot.get("weekday"))>=0&&number(slot.get("weekday"))<=6&&Objects.toString(slot.get("open"),"").matches("([01][0-9]|2[0-3]):[0-5][0-9]")&&Objects.toString(slot.get("close"),"").matches("([01][0-9]|2[0-3]):[0-5][0-9]")&&slot.get("overnight") instanceof Boolean,422,"INVALID_OPENING_HOURS");require(Boolean.TRUE.equals(slot.get("overnight"))||slot.get("close").toString().compareTo(slot.get("open").toString())>0,422,"INVALID_OPENING_HOURS");}var normalized=map("name",name,"category_ids",raw.get("category_ids"),"latitude",lat,"longitude",lon,"opening_hours",hours,"price",price,"currency","VND");if(raw.get("address")!=null){require(raw.get("address") instanceof String,422,"INVALID_ADDRESS");normalized.put("address",Normalizer.normalize(text(raw,"address",1024),Normalizer.Form.NFC).replaceAll("\\s+"," "));}return normalized;}
    static double score(Map<String,Object> normalized,Map<?,?> candidate){String a=normalized.get("name").toString().toLowerCase(Locale.ROOT),b=candidate.get("name").toString().toLowerCase(Locale.ROOT);double name=a.equals(b)?1:0;double lat=Double.parseDouble(normalized.get("latitude").toString())-Double.parseDouble(candidate.get("latitude").toString()),lon=Double.parseDouble(normalized.get("longitude").toString())-Double.parseDouble(candidate.get("longitude").toString());double proximity=Math.max(0,1-Math.sqrt(lat*lat+lon*lon)/0.01);return Math.round((name*0.7+proximity*0.3)*10000)/10000.0;}
    private void ingest(UUID job,Map<String,Object>src,Map<String,Object>raw){UUID source=(UUID)src.get("source_id");String hash=hash(s.encode(canonical(raw)));String external=raw.get("external_id") instanceof String x&&!x.isBlank()&&x.length()<=1024?x.strip():"quarantine:"+hash;UUID rawId=UUID.randomUUID();var rows=s.queryForList(INSERT_RAW_RECORDS_26,rawId,source,external,job,s.encode(raw),hash);rawId=(UUID)rows.getFirst().get("raw_id");if(s.queryForObject(SELECT_IMPORT_ITEMS_27,Long.class,job,rawId)>0)return;
        UUID item=UUID.randomUUID(),command=UUID.randomUUID(),proposed=UUID.randomUUID();Map<String,Object>normalized;String error=null;try{require(!external.startsWith("quarantine:"),422,"EXTERNAL_ID_REQUIRED");normalized=normalize(raw);}catch(Exception e){normalized=Map.of();error="NORMALIZATION_INVALID";}
        var links=s.queryForList(SELECT_SOURCE_PLACE_LINKS_9,source,external);String op="CREATE",status=error==null?"PENDING":"FAILED";Long expected=0L;
        if(error==null&&!links.isEmpty()){var link=links.getFirst();proposed=(UUID)link.get("place_id");expected=number(link.get("catalog_version"));op="UPDATE";if(hash.equals(link.get("last_hash"))){op="SKIP";status="SKIPPED";}}
        s.update(INSERT_IMPORT_ITEMS_28,item,job,source,rawId,command,op,status,proposed,s.encode(normalized),expected,error);
        if(error!=null)return;
        if(links.isEmpty()) {var candidates=connector.candidates(normalized);Object list=candidates.get("items");require(list instanceof List<?>&&((List<?>)list).size()<=100,503,"CANDIDATE_INVALID_RESPONSE");if(!((List<?>)list).isEmpty()){for(Object c:(List<?>)list){var candidate=(Map<?,?>)c;double score=score(normalized,candidate);require(score>=0&&score<=1,503,"CANDIDATE_INVALID_RESPONSE");s.update(INSERT_MATCH_CANDIDATES_29,UUID.randomUUID(),rawId,id(candidate.get("place_id")),score,s.encode(candidate));}s.update(UPDATE_IMPORT_ITEMS_30,item);return;}}
        if(status.equals("PENDING"))command(item);
    }
    private Map<String,Object> commandFields(Map<String,Object> normalized){var fields=new LinkedHashMap<String,Object>();for(String field:List.of("name","category_ids","latitude","longitude","opening_hours","price","currency"))fields.put(field,normalized.get(field));return fields;}
    private void command(UUID item){var r=s.one(SELECT_IMPORT_ITEMS_31,item);var src=source((UUID)r.get("source_id"),true);permitted(src);var payload=map("command_id",r.get("command_id"),"source_id",r.get("source_id"),"external_id",r.get("external_id"),"source_version",src.get("version"),"source_hash",r.get("content_hash"),"proposed_place_id",r.get("proposed_place_id"),"normalized",commandFields(s.decode(r.get("normalized_payload"))),"expected_catalog_version",r.get("expected_catalog_version"));s.event((UUID)r.get("command_id"),number(r.get("version")),"ingestion.place.upsert-requested.v1",payload);s.update(UPDATE_IMPORT_ITEMS_32,item);}
    private String publicItemStatus(Map<String,Object>r){String status=r.get("status").toString();return switch(status){case "SENT"->"PENDING";case "DUPLICATE"->"APPLIED";case "SKIPPED"->"REVIEW_REJECTED".equals(r.get("error_code"))?"REJECTED":"APPLIED";default->status;};}
    private Map<String,Object> itemResponse(Map<String,Object>r){return map("item_id",r.get("import_item_id"),"command_id",r.get("command_id"),"status",publicItemStatus(r),"proposed_place_id",r.get("proposed_place_id"),"error_code",r.get("error_code"),"version",r.get("version"));}
    public Map<String,Object> items(UUID job,String kind){var jobRow=s.one(SELECT_IMPORT_JOBS_15,job);long pageVersion=number(jobRow.get("version"));if(kind.equals("candidates")){var rows=s.queryForList(SELECT_MATCH_CANDIDATES_33,job);return s.page(rows.stream().map(r->s.decode(r.get("evidence"))).toList(),pageVersion);}var rows=s.queryForList(SELECT_IMPORT_ITEMS_34+(kind.equals("errors")?" AND error_code IS NOT NULL":"")+" ORDER BY import_item_id",job);return s.page(rows.stream().map(r->kind.equals("errors")?map("item_id",r.get("import_item_id"),"error_code",r.get("error_code"),"message","Import item requires operator review; raw details are redacted"):itemResponse(r)).toList(),pageVersion);}
    public Map<String,Object> decide(UUID actor,UUID item,String expected,Map<String,Object>b){s.guardActor(actor);var r=s.one(SELECT_IMPORT_ITEMS_35,item);require(number(r.get("version"))==version(expected),409,"VERSION_CONFLICT");require("NEEDS_REVIEW".equals(r.get("status")),422,"ITEM_NOT_REVIEWABLE");String action=text(b,"action",20);text(b,"reason",1024);require(Set.of("MATCH","CREATE","REJECT").contains(action),400,"INVALID_DECISION");if(action.equals("REJECT")){s.update(UPDATE_IMPORT_ITEMS_36,item);}else{UUID proposed=action.equals("MATCH")?id(b.get("place_id")):(UUID)r.get("proposed_place_id");long expectedVersion=0;if(action.equals("MATCH")){var candidate=s.one(SELECT_MATCH_CANDIDATES_37,r.get("raw_id"),proposed);var evidence=s.decode(candidate.get("evidence"));expectedVersion=number(evidence.get("version"));require(expectedVersion>0,422,"CANDIDATE_VERSION_REQUIRED");s.update(UPDATE_MATCH_CANDIDATES_38,proposed,actor,r.get("raw_id"));}s.update(UPDATE_IMPORT_ITEMS_39,proposed,action.equals("MATCH")?"UPDATE":"CREATE",expectedVersion,item);command(item);}audit(actor,"item",item,"REVIEWED");settle((UUID)r.get("job_id"));return itemResponse(s.one(SELECT_IMPORT_ITEMS_40,item));}
    public Map<String,Object> retry(UUID actor,UUID job,String expected){s.guardActor(actor);var r=s.one(SELECT_IMPORT_JOBS_21,job);require(number(r.get("version"))==version(expected),409,"VERSION_CONFLICT");var src=source((UUID)r.get("source_id"),true);permitted(src);require(!"CANCELLED".equals(r.get("status")),422,"JOB_CANCELLED");var items=s.queryForList(SELECT_IMPORT_ITEMS_41,UUID.class,job);for(UUID item:items)command(item);s.update(UPDATE_IMPORT_JOBS_42,src.get("version"),job);audit(actor,"job",job,"RETRIED");settle(job);return job(job);}
    public Map<String,Object> cancel(UUID actor,UUID job,String expected){s.guardActor(actor);var r=s.one(SELECT_IMPORT_JOBS_21,job);require(number(r.get("version"))==version(expected),409,"VERSION_CONFLICT");require(!"SUCCEEDED".equals(r.get("status")),422,"JOB_ALREADY_SUCCEEDED");s.update(UPDATE_IMPORT_JOBS_43,job);audit(actor,"job",job,"CANCELLED");return job(job);}
    void settle(UUID job){var r=s.one(SELECT_IMPORT_JOBS_21,job);if(!Boolean.TRUE.equals(r.get("fetch_complete"))||"CANCELLED".equals(r.get("status")))return;long outstanding=s.queryForObject(SELECT_IMPORT_ITEMS_44,Long.class,job);if(outstanding>0)return;long failures=s.queryForObject(SELECT_IMPORT_ITEMS_45,Long.class,job);String status=failures>0?"PARTIAL":"SUCCEEDED";s.update(UPDATE_IMPORT_JOBS_46,status,job);if(failures==0){s.update(INSERT_SOURCE_CHECKPOINTS_47,r.get("source_id"),r.get("cursor_after")==null?"{}":s.encode(map("cursor",s.decode(r.get("cursor_after")).getOrDefault("checkpoint",s.decode(r.get("cursor_after")).get("cursor")))));s.update(UPDATE_DATA_SOURCES_48,r.get("source_id"));}}
    public void result(Map<String,Object>event){String type=event.get("event_type").toString();require(number(event.get("schema_version"))==1&&Set.of("catalog.place-import.applied.v1","catalog.place-import.rejected.v1").contains(type),422,"UNSUPPORTED_EVENT");UUID eventId=id(event.get("event_id"));@SuppressWarnings("unchecked")var p=(Map<String,Object>)event.get("payload");UUID command=id(p.get("command_id"));var rows=s.queryForList(SELECT_IMPORT_ITEMS_49,command);require(!rows.isEmpty(),422,"UNKNOWN_COMMAND");var r=rows.getFirst();require(r.get("source_id").equals(id(p.get("source_id"))),422,"RESULT_SOURCE_MISMATCH");if(s.update(INSERT_INBOX_EVENTS_50,eventId)==0)return;if(Set.of("APPLIED","DUPLICATE","SKIPPED").contains(r.get("status")))return;var src=source((UUID)r.get("source_id"),true);permitted(src);if(type.endsWith("applied.v1")){UUID place=id(p.get("place_id"));long version=number(p.get("catalog_version"));require(version>0,422,"INVALID_CATALOG_VERSION");s.update(UPDATE_IMPORT_ITEMS_51,place,version,command);s.update(INSERT_SOURCE_PLACE_LINKS_52,UUID.randomUUID(),r.get("source_id"),r.get("external_id"),place,r.get("content_hash"),version);}else{String code=Objects.toString(p.get("error_code"),"CATALOG_REJECTED");s.update(UPDATE_IMPORT_ITEMS_53,code.contains("CONFLICT")?"NEEDS_REVIEW":"FAILED",code,command);}settle((UUID)r.get("job_id"));}
    public void markFetchFailure(UUID job){s.update(UPDATE_IMPORT_JOBS_54,job);}
}
